def _fetch(params: dict) -> httpx.Response:
    last_detail, last_status = "", None
    for attempt in (1, 2):
        try:
            r = httpx.get(ENDPOINT, params=params, headers=UA,
                          timeout=30.0, follow_redirects=True)
        except httpx.HTTPError as e:
            last_detail, last_status = f"transport failure: {e!r}", None
            time.sleep(2.0)
            continue
        if r.status_code < 400:
            return r
        last_detail, last_status = r.text[:500], r.status_code
        if r.status_code in (429, 500, 502, 503, 504) and attempt == 1:
            time.sleep(2.0)
            continue
        break
    raise RuntimeError(json.dumps({"status": last_status,
                                   "detail": last_detail}))


def parse(j: dict) -> dict:
    feats = j["results"]["geojson"]["features"]
    rows = [f["properties"] for f in feats]
    total = len(rows)
    kept = rows[-MAX_ROWS:] if total > MAX_ROWS else rows
    out = {"rows": kept, "truncated": total > MAX_ROWS,
           "total_rows": total}
    if kept:
        out["returned_span"] = [str(kept[0].get("time_str")),
                                str(kept[-1].get("time_str"))]
    if out["truncated"]:
        out["omitted"] = (f"{total - MAX_ROWS} earlier rows omitted; "
                          "narrow the time window to retrieve them")
    return out


@mcp.tool()
def hydrocron_timeseries(feature_id: str, feature: str = "Reach",
                         start_time: str = "2023-01-01T00:00:00Z",
                         end_time: str = "2026-12-31T00:00:00Z",
                         fields: str = "reach_id,time_str,wse,width") -> dict:
    """SWOT river time series from PO.DAAC Hydrocron.

    feature: 'Reach' or 'Node'; feature_id: SWORD id (e.g.
    '63470800171'). wse is water surface elevation in metres on the
    EGM2008 geoid; width in metres; fill values are large negatives,
    filter before use. Anonymous; source of record: PO.DAAC."""
    try:
        r = _fetch({"feature": feature, "feature_id": feature_id,
                    "start_time": start_time, "end_time": end_time,
                    "fields": fields})
        return {"feature": feature, "feature_id": feature_id,
                **parse(r.json()),
                "retrieved_at": dt.datetime.now(dt.timezone.utc)
                .isoformat(timespec="seconds"),
                "request_url": str(r.request.url),
                "server_version": VERSION}
    except RuntimeError as e:
        info = json.loads(str(e))
        return {"error": "hydrocron request failed",
                "source": "hydrocron", **info}
    except (KeyError, IndexError, ValueError, TypeError) as e:
        return {"error": "unexpected response shape from hydrocron; "
                         "the upstream schema may have changed",
                "source": "hydrocron", "status": None,
                "detail": repr(e)[:500]}


def offline_test() -> int:
    fails = 0

    def check(name, cond):
        nonlocal fails
        print(f"{'PASS' if cond else 'FAIL'} {name}")
        fails += 0 if cond else 1

    p = parse(json.loads(EMBEDDED_FIXTURE))
    check("parser vs embedded fixture",
          p["total_rows"] == 2 and "wse" in p["rows"][0]
          and "returned_span" in p)
    check("tail kept on synthetic",
          parse({"results": {"geojson": {"features": [
              {"properties": {"time_str": str(i)}} for i in range(700)
          ]}}})["rows"][0]["time_str"] == "200")
    print(f"offline test: {2 - fails}/2 PASS")
    return fails


def selftest() -> int:
    d = hydrocron_timeseries("63470800171",
                             start_time="2024-01-25T00:00:00Z",
                             end_time="2024-03-29T00:00:00Z")
    ok = d.get("total_rows", 0) > 0 and "retrieved_at" in d
    print(f"{'PASS' if ok else 'FAIL'} live probe "
          f"({d.get('total_rows')} rows)")
    return 0 if ok else 1


if __name__ == "__main__":
    if "--test" in sys.argv:
        raise SystemExit(offline_test())
    if "--selftest" in sys.argv:
        raise SystemExit(selftest())
    mcp.run()
